import pytest
from datetime import datetime, timedelta

@pytest.fixture
def admin_user():
    return {"username": "admin", "password": "password"}

@pytest.fixture
def patient_user():
    return {"username": "patient", "password": "password"}

@pytest.fixture
def doctor_user():
    return {"username": "doctor", "password": "password"}

@pytest.fixture
def specialty():
    return {"name": "Cardiology"}

@pytest.fixture
def doctor():
    return {"name": "John Doe", "specialties": [specialty]}

@pytest.fixture
def patient():
    return {"name": "Jane Doe", "medical_info": "some info", "general_info": "some general info"}

@pytest.fixture
def hospital():
    return {"name": "Hospital Name"}

@pytest.fixture
def system_under_test():
    # Mock the system under test
    pass

def test_VIRTUA_4_1_1(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that the system can handle 10,000+ users concurrently
    users = [patient_user] * 10000
    response = system_under_test.register_users(users)
    assert response.status_code == 200

def test_VIRTUA_4_1_2(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that the system has a response time of <=2 seconds for critical functionality
    start_time = datetime.now()
    response = system_under_test.register_patient(patient)
    end_time = datetime.now()
    assert (end_time - start_time).total_seconds() <= 2

def test_VIRTUA_4_1_3(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that the system has a response time of <=4 seconds for other functions during peak period
    start_time = datetime.now()
    response = system_under_test.add_specialty(specialty)
    end_time = datetime.now()
    assert (end_time - start_time).total_seconds() <= 4

def test_VIRTUA_4_1_4(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that the system has 99.999% Availability (10 minutes outage per month on every 4th Sunday night between 12:00 AM – 12:10 AM)
    # This test is difficult to automate, so we'll just test that the system is available at other times
    start_time = datetime.now()
    response = system_under_test.health_check()
    end_time = datetime.now()
    assert response.status_code == 200

def test_VIRTUA_4_2_1(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that patient registration is possible by providing personal, medical and general information
    response = system_under_test.register_patient(patient)
    assert response.status_code == 200

def test_VIRTUA_4_2_2(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that admin can add specialties of doctors for which the hospital will give treatment
    response = system_under_test.add_specialty(specialty)
    assert response.status_code == 200

def test_VIRTUA_4_2_3(system_under_test, admin_user, patient_user, doctor_user, specialty, doctor, patient, hospital):
    # Test that admin can register doctors into the system
    response = system_under_test.register_doctor(doctor)
    assert response.status_code == 200
